// Improved Express application with security best practices
// Error handling, input validation, and security middleware implemented

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, query, validationResult } = require('express-validator');

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet for HTTP security headers (X-Frame-Options, CSP, etc.)
app.use(helmet());

// 2. CORS configuration - restrict to trusted origins
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

// 3. Rate limiting - prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// 4. Request body size limits - prevent memory exhaustion
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Request logging with Morgan
const logFormat = process.env.NODE_ENV === 'production' ? 'combined' : 'dev';
app.use(morgan(logFormat));

// ============================================================================
// MIDDLEWARE FUNCTIONS
// ============================================================================

// Authentication middleware - validates JWT or API key
const authenticateUser = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  const apiKey = req.headers['x-api-key'];

  if (!token && !apiKey) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Missing authentication token or API key',
    });
  }

  // TODO: Implement proper JWT verification or API key validation
  // For now, this is a placeholder
  if (token) {
    // Verify JWT token here
    try {
      // const decoded = jwt.verify(token, process.env.JWT_SECRET);
      // req.user = decoded;
      req.user = { id: 1, authenticated: true }; // Placeholder
    } catch (error) {
      return res.status(403).json({ error: 'Invalid token' });
    }
  }

  next();
};

// Input validation middleware
const validateHealthQuery = [
  query('*').isEmpty().custom(() => {
    throw new Error('No query parameters allowed');
  }).optional(),
];

// ============================================================================
// ROUTES
// ============================================================================

// Health check endpoint - no sensitive data
app.get('/health', (req, res, next) => {
  try {
    // Validate that no unexpected query parameters are provided
    if (Object.keys(req.query).length > 0) {
      return res.status(400).json({
        error: 'Bad request',
        message: 'No query parameters expected on /health endpoint',
      });
    }

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development',
    });
  } catch (error) {
    next(error);
  }
});

// Protected users endpoint - requires authentication
app.get('/users', authenticateUser, (req, res, next) => {
  try {
    // Validate query parameters (pagination, filtering)
    const limit = parseInt(req.query.limit || '10', 10);
    const offset = parseInt(req.query.offset || '0', 10);

    // Input validation
    if (isNaN(limit) || isNaN(offset) || limit < 1 || limit > 100 || offset < 0) {
      return res.status(400).json({
        error: 'Bad request',
        message: 'Invalid pagination parameters: limit must be 1-100, offset must be >= 0',
      });
    }

    // Mock data - in production, this would come from a database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply pagination
    const paginatedUsers = allUsers.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        total: allUsers.length,
        limit,
        offset,
      },
    });
  } catch (error) {
    next(error);
  }
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 Handler - must come after all other routes
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist`,
  });
});

// Global error handler - must be last middleware
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const statusCode = err.statusCode || err.status || 500;

  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: isDevelopment ? err.stack : undefined,
    path: req.path,
    method: req.method,
  });

  // Don't expose stack traces in production
  const response = {
    error: 'Internal server error',
    message: isDevelopment ? err.message : 'An unexpected error occurred',
  };

  if (isDevelopment) {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

// Graceful shutdown handler
const gracefulShutdown = () => {
  console.log('Received shutdown signal, closing gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });

  // Force shutdown after 10 seconds
  setTimeout(() => {
    console.error('Forced shutdown due to timeout');
    process.exit(1);
  }, 10000);
};

process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

// Start server
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

# Security Review: app.js

## Executive Summary

The original `app.js` contains **11 security and reliability issues**, with **1 critical**, **3 high**, and **7 medium** severity findings. The most critical issue is an unauthenticated endpoint exposing sensitive user data. Below are detailed findings and recommended fixes.

---

## Critical Issues

### 1. ⚠️ Unauthenticated `/users` Endpoint (Line 11-16)

**Severity:** 🔴 **CRITICAL**

**Issue:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Risk:**
- Exposes sensitive user data (email addresses, IDs) to any person on the internet
- No authentication or authorization checks
- Violates privacy principles and data protection regulations (GDPR, CCPA, etc.)
- Could enable targeted phishing or social engineering attacks

**Attack Scenario:**
```
1. Attacker discovers the /users endpoint
2. Makes GET request to http://your-api.com/users
3. Receives full list of user emails
4. Uses emails for phishing campaign
```

**Recommended Fix:**
```javascript
// Add authentication middleware
const authenticateUser = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  // Verify JWT or session token
  next();
};

// Protect the endpoint
app.get('/users', authenticateUser, (req, res) => {
  // ... endpoint logic
});
```

---

## High Priority Issues

### 2. Missing Helmet Middleware (Line 5)

**Severity:** 🟠 **HIGH**

**Issue:**
No HTTP security headers are set by default.

**Risk:**
- Vulnerable to clickjacking attacks (no X-Frame-Options)
- MIME-type sniffing attacks (no X-Content-Type-Options)
- XSS attacks (no X-XSS-Protection)
- Missing HSTS header leaves SSL/TLS negotiation vulnerable

**Recommended Fix:**
```javascript
const helmet = require('helmet');
app.use(helmet());

// This adds protective headers:
// - X-Frame-Options: DENY
// - X-Content-Type-Options: nosniff
// - Strict-Transport-Security: max-age=15552000
// - Content-Security-Policy: ...
```

---

### 3. No CORS Configuration (Line 5)

**Severity:** 🟠 **HIGH**

**Issue:**
CORS is not configured, meaning the API accepts requests from any origin.

**Risk:**
- Malicious websites can make requests to your API on behalf of their visitors
- Can enable data theft, unauthorized operations, or CSRF attacks
- User authentication tokens in cookies are automatically sent cross-origin

**Attack Scenario:**
```
1. Attacker creates malicious website
2. Embedded script makes fetch() request to your API
3. User's browser automatically includes authentication cookies
4. Attacker's site receives sensitive data
```

**Recommended Fix:**
```javascript
const cors = require('cors');

const corsOptions = {
  origin: ['https://yourdomain.com', 'https://app.yourdomain.com'],
  credentials: true,
  methods: ['GET', 'POST'],
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));
```

---

### 4. No Rate Limiting (Line 5)

**Severity:** 🟠 **HIGH**

**Issue:**
Any client can make unlimited requests to the server.

**Risk:**
- Denial of Service (DoS) attacks
- Brute force attacks on authentication endpoints
- API abuse by competitors or malicious actors
- Uncontrolled server resource consumption

**Attack Scenario:**
```
1. Attacker runs script sending 10,000 requests/second
2. Server resources exhausted
3. Legitimate users cannot access the service
```

**Recommended Fix:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per window
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);
```

---

## Medium Priority Issues

### 5. No Input Validation (Lines 7, 11)

**Severity:** 🟡 **MEDIUM**

**Issue:**
Routes don't validate incoming data, query parameters, or request bodies.

**Risk:**
- Allows unexpected inputs to reach application logic
- Can lead to unexpected behavior or crashes
- Opens door to injection attacks (though limited here due to simple logic)

**Recommended Fix:**
```javascript
app.get('/health', (req, res) => {
