  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, you might want to alert monitoring service
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;
```

### **Key Improvements:**

| Issue | Solution |
|-------|----------|
| Missing security headers | Added `helmet` middleware |
| No rate limiting | Added `express-rate-limit` |
| No input validation | Query parameter validation with type checking |
| NoSQL injection risk | Added `mongo-sanitize` middleware |
| Missing error handling | Try-catch blocks + global error handler |
| Unhandled rejections | Process-level rejection/exception handlers |
| No request size limits | Limited JSON/URL-encoded body size to 1MB |
| No logging | Added error logging with context |
| No 404 handling | Added 404 middleware |
| No graceful shutdown | Added SIGTERM handler |

