// Production-ready Express application with security and error handling best practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const dotenv = require('dotenv');

// Load environment variables
dotenv.config();

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE (in recommended order)
// ============================================================================

// 1. Security headers middleware (must be early)
app.use(helmet());

// 2. Trust proxy (for rate limiting behind reverse proxies)
app.set('trust proxy', process.env.TRUST_PROXY || 1);

// 3. Request logging middleware (before auth for audit trail)
app.use(morgan('combined'));

// 4. Body parser middleware
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// 5. Rate limiting middleware (apply globally)
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(globalLimiter);

// 6. Stricter rate limiting for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 requests per 15 minutes for auth endpoints
  skipSuccessfulRequests: true, // Don't count successful requests
  message: 'Too many authentication attempts, please try again later.',
});

// ============================================================================
// AUTHENTICATION & AUTHORIZATION MIDDLEWARE
// ============================================================================

/**
 * Mock authentication middleware
 * In production, verify JWT tokens or session cookies
 */
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      error: 'Unauthorized',
      message: 'Missing or invalid authorization header',
    });
  }

  // Mock token validation
  const token = authHeader.substring(7);
  if (token === 'valid-test-token') {
    req.user = { id: 1, role: 'admin' };
    return next();
  }

  return res.status(403).json({
    error: 'Forbidden',
    message: 'Invalid token',
  });
};

/**
 * Mock authorization middleware for admin role
 */
const authorizeAdmin = (req, res, next) => {
  if (req.user && req.user.role === 'admin') {
    return next();
  }

  return res.status(403).json({
    error: 'Forbidden',
    message: 'Admin access required',
  });
};

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

/**
 * Sanitize and validate user ID parameter
 */
const validateUserId = (req, res, next) => {
  const userId = req.params.id;

  if (!userId || !/^\d+$/.test(userId)) {
    return res.status(400).json({
      error: 'Bad Request',
      message: 'Invalid user ID format',
    });
  }

  next();
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint (no authentication required)
 * Safe for load balancers and monitoring
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

/**
 * Get all users (PROTECTED - authentication + authorization required)
 * Only accessible with valid token
 */
app.get('/users', authLimiter, authenticate, authorizeAdmin, (req, res) => {
  // Return sanitized user data without sensitive information
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];

  res.json({
    success: true,
    data: users,
    count: users.length,
  });
});

/**
 * Get user by ID (PROTECTED - authentication required)
 */
app.get('/users/:id', authenticate, validateUserId, (req, res) => {
  const userId = parseInt(req.params.id, 10);

  // Mock user lookup (in production: query database)
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];

  const user = users.find((u) => u.id === userId);

  if (!user) {
    return res.status(404).json({
      error: 'Not Found',
      message: `User with ID ${userId} not found`,
    });
  }

  res.json({
    success: true,
    data: user,
  });
});

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * 404 Not Found handler
 * Must be after all other routes
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: `The requested endpoint ${req.method} ${req.path} does not exist`,
  });
});

/**
 * Global error handling middleware
 * Must be last middleware
 * Catches all synchronous errors and passed errors from async routes
 */
app.use((err, req, res, next) => {
  // Log error details (don't expose sensitive info to client)
  const errorId = Date.now().toString(36);
  console.error(`[ERROR ${errorId}]`, {
    message: err.message,
    stack: err.stack,
    url: req.originalUrl,
    method: req.method,
    ip: req.ip,
  });

  // Determine status code
  const statusCode = err.statusCode || err.status || 500;

  // Prepare error response (don't leak stack traces in production)
  const response = {
    error: 'Internal Server Error',
    message:
      process.env.NODE_ENV === 'production'
        ? 'An error occurred processing your request'
        : err.message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    errorId, // Helps users reference the error in logs
  };

  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

let server;

/**
 * Start the server with error handling
 */
const startServer = () => {
  try {
    server = app.listen(PORT, () => {
      console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
    });

    // Handle server errors
    server.on('error', (err) => {
      if (err.code === 'EADDRINUSE') {
        console.error(`Error: Port ${PORT} is already in use`);
      } else {
        console.error('Server error:', err);
      }
      process.exit(1);
    });
  } catch (err) {
    console.error('Failed to start server:', err);
    process.exit(1);
  }
};

// ============================================================================
// PROCESS-LEVEL EXCEPTION HANDLERS
// ============================================================================

/**
 * Handle uncaught exceptions
 * These are errors thrown in synchronous code that aren't caught
 */
process.on('uncaughtException', (err) => {
  console.error('UNCAUGHT EXCEPTION:', err);
  // In production, you may want to exit and restart the process
  process.exit(1);
});

/**
 * Handle unhandled promise rejections
 * These are errors in promises that don't have .catch() handlers
 */
process.on('unhandledRejection', (reason, promise) => {
  console.error('UNHANDLED REJECTION at:', promise, 'reason:', reason);
  // In production, you may want to exit and restart the process
  process.exit(1);
});

/**
 * Graceful shutdown
 */
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  if (server) {
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  }
});

process.on('SIGINT', () => {
  console.log('SIGINT signal received: closing HTTP server');
  if (server) {
    server.close(() => {
      console.log('HTTP server closed');
      process.exit(0);
    });
  }
});

// ============================================================================
// START SERVER
// ============================================================================

// Only start server if this is the main module (not imported as a module)
if (require.main === module) {
  startServer();
}

module.exports = app;

