// Enhanced application with security best practices
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const dotenv = require('dotenv');

dotenv.config();

const app = express();
const PORT = process.env.PORT || 3000;

// Security middleware
app.use(helmet()); // Sets various HTTP headers
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb' })); // Limit URL-encoded payloads

// CORS configuration (restrict to trusted origins)
const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
app.use(cors({
  origin: allowedOrigins,
  credentials: true,
  optionsSuccessStatus: 200
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Health check endpoint (no rate limiting)
const healthLimiter = rateLimit({
  windowMs: 1 * 60 * 1000,
  max: 200,
});

// Request validation helper
const validateQueryParams = (req, allowedParams) => {
  const queryKeys = Object.keys(req.query);
  const invalidParams = queryKeys.filter(key => !allowedParams.includes(key));

  if (invalidParams.length > 0) {
    throw new Error(`Invalid query parameters: ${invalidParams.join(', ')}`);
  }
};

// Error handling middleware
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Routes
app.get('/health', healthLimiter, asyncHandler(async (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
}));

app.get('/users', limiter, asyncHandler(async (req, res) => {
  // Validate query parameters
  validateQueryParams(req, ['id', 'name']); // Only allow specific params

  // Input validation examples
  if (req.query.id && isNaN(parseInt(req.query.id))) {
    return res.status(400).json({ error: 'Invalid id parameter' });
  }

  if (req.query.name && req.query.name.length > 100) {
    return res.status(400).json({ error: 'Name parameter too long' });
  }

  // Mock data (in production, fetch from secured database)
  const users = [
    { id: 1, name: 'Alice' }, // Don't expose email in response
    { id: 2, name: 'Bob' },
  ];

  // Filter based on validated input
  let filtered = users;
  if (req.query.id) {
    filtered = filtered.filter(u => u.id === parseInt(req.query.id));
  }
  if (req.query.name) {
    filtered = filtered.filter(u => 
      u.name.toLowerCase().includes(req.query.name.toLowerCase())
    );
  }

  res.json(filtered);
}));

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't leak error details in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  });
});

// Graceful shutdown
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

